export function shell({active='components',content=''}){return `<header class="topbar"><img src="../shared/logo.png" alt="Logo"><span>管理者</span></header><div class="layout"><aside class="sidebar"><div class="collapse">☰</div><div class="item">新規アップロード</div><div class="item">マイタスク</div><div class="item">業務ルール設定</div><div class="item sub">帳票タイプ設定</div><div class="item sub">マスタデータ設定</div><div class="item sub">モデル設定</div><a class="item sub" href="./api-settings.html" data-nav="api-settings">API設定</a><hr><a class="${active==='components'?'active':''}" href="./components.html" data-nav="components">コンポーネント</a><a class="${active==='states'?'active':''}" href="./states.html" data-nav="states">状態一覧</a></aside><main class="content">${content}</main></div>`}
export function mount(content){document.getElementById('app').innerHTML=content;}
document.addEventListener('click',event=>{const target=event.target.closest('[data-nav]');if(!target||window.parent===window)return;window.parent.postMessage({type:'interaction-prd:navigate',pageId:target.dataset.nav},window.location.origin);});
